// ADR-047 (S3, port plan §3): the module «Защита» ships its own ru/en catalog (apps/production-protect/src/locales/
// catalog.generated.json, generated by build-protect.mjs and embedded into protect-ui.js). Checks: ru/en key and
// placeholder parity; the consent text is the one of 722fae8 (digest of PROTECT_CONSENT_KEYS); production keys never
// collide with vendored keys; the production overrides (owner decision Q1: DNR required, no restart texts) are the only
// texts that differ from the vendored catalog and never touch consent keys; every key the UI bundle asks for exists;
// the 21 production languages map to ru (ru) or en (all others, with the fallback note); production _locales keep no
// module key.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync } from 'node:fs';
import { join, resolve } from 'node:path';
import test from 'node:test';
import { build } from 'esbuild';
import { PRODUCTION_LANGUAGES } from '../../production-languages.mjs';

const root = resolve(import.meta.dirname, '../../..');
const vendor = join(root, 'vendor/protect-722fae8');
const readJson = (path) => JSON.parse(readFileSync(path, 'utf8'));
const catalog = readJson(join(root, 'apps/production-protect/src/locales/catalog.generated.json'));
const vendorRu = readJson(join(vendor, 'apps/extension/_locales/ru/messages.json'));
const vendorEn = readJson(join(vendor, 'apps/extension/_locales/en/messages.json'));
const ownRu = readJson(join(root, 'apps/production-protect/src/locales/ru.json'));
const ownEn = readJson(join(root, 'apps/production-protect/src/locales/en.json'));
const overrides = readJson(join(root, 'apps/production-protect/src/locales/overrides.json')).messages;
const launcher = readJson(join(root, 'apps/production-protect/src/locales/firewall-launcher.json'));
const branding = readJson(join(root, 'apps/production-protect/src/locales/firewall-branding.json'));
const findings = readJson(join(root, 'apps/production-protect/src/locales/findings.json'));
const sha256 = (text) => createHash('sha256').update(Buffer.from(text, 'utf8')).digest('hex');

/** Imports a TS module of the repository through an in-memory esbuild bundle. */
async function load(entry) {
  const result = await build({ entryPoints: [entry], bundle: true, format: 'esm', platform: 'neutral', write: false, logLevel: 'silent', absWorkingDir: root });
  return import('data:text/javascript;base64,' + Buffer.from(result.outputFiles[0].text).toString('base64'));
}

function tokens(message) {
  return [...message.matchAll(/\$([a-z_][a-z0-9_]*)\$/gi)].map((m) => m[1].toLowerCase()).sort();
}

test('ru/en parity: the same keys, placeholders and substitution tokens; no empty text', () => {
  assert.deepEqual(Object.keys(catalog), ['ru', 'en']);
  assert.deepEqual(Object.keys(catalog.ru), Object.keys(catalog.en));
  assert.ok(Object.keys(catalog.ru).length > 600, 'module catalog size ' + Object.keys(catalog.ru).length);
  for (const key of Object.keys(catalog.ru)) {
    const ru = catalog.ru[key];
    const en = catalog.en[key];
    assert.deepEqual(Object.keys(ru.placeholders ?? {}).sort(), Object.keys(en.placeholders ?? {}).sort(), key);
    assert.deepEqual(tokens(ru.message), tokens(en.message), key);
    for (const name of tokens(ru.message)) assert.ok(Object.hasOwn(ru.placeholders ?? {}, name), key + ': $' + name + '$ has a placeholder');
    assert.ok(ru.message.trim().length > 0 && en.message.trim().length > 0, key + ': empty text');
    assert.notEqual(en.message, key, key + ': text equals its key');
  }
});

test('consent text unchanged: digest of PROTECT_CONSENT_KEYS (722fae8) over the shipped catalog', async () => {
  const consent = await load(join(vendor, 'packages/engine/src/protect/consent.ts'));
  assert.equal(consent.PROTECT_CONSENT_KEYS.length, 18);
  for (const key of consent.PROTECT_CONSENT_KEYS) {
    assert.ok(Object.hasOwn(catalog.ru, key), key);
    assert.equal(catalog.ru[key].message, vendorRu[key].message, key + ' (ru) is the vendored text');
    assert.equal(catalog.en[key].message, vendorEn[key].message, key + ' (en) is the vendored text');
  }
  const input = consent.protectConsentDigestInput((key) => catalog.ru[key].message, (key) => catalog.en[key].message);
  assert.equal(sha256(input), consent.PROTECT_CONSENT_DIGEST.sha256);
  assert.equal(consent.PROTECT_CONSENT_DIGEST.sha256, '08ca812843b9c1d3d87f957d3ae65ce8748c5ae0732967cf1a330172c43feb6c');
});

test('production module keys are separate from vendored keys and present in both languages', () => {
  assert.deepEqual(Object.keys(ownRu).sort(), Object.keys(ownEn).sort());
  for (const key of Object.keys(ownRu)) {
    assert.equal(Object.hasOwn(vendorRu, key), false, 'collides with a vendored key: ' + key);
    assert.equal(catalog.ru[key].message, ownRu[key].message, key);
    assert.equal(catalog.en[key].message, ownEn[key].message, key);
  }
});

test('overrides (owner decision Q1): only these texts differ from 722fae8, never a consent key, no restart wording left', () => {
  const keys = Object.keys(overrides).sort();
  assert.deepEqual(keys, ['fw_blocking_restart', 'protect_disabled_notice_rules_pending', 'protect_gpc_restart_hint', 'protect_reason_blocking_unavailable']);
  for (const key of Object.keys(catalog.ru)) {
    if (Object.hasOwn(ownRu, key)) continue;
    const changed = catalog.ru[key].message !== vendorRu[key].message || catalog.en[key].message !== vendorEn[key].message;
    assert.equal(changed, keys.includes(key), key + (changed ? ' differs from the vendored text without an override' : ' override not applied'));
    if (keys.includes(key)) {
      assert.equal(catalog.ru[key].message, overrides[key].ru, key);
      assert.equal(catalog.en[key].message, overrides[key].en, key);
      assert.equal(key.startsWith('protect_consent_'), false, key);
      assert.deepEqual(tokens(overrides[key].ru), tokens(vendorRu[key].message), key);
      assert.deepEqual(tokens(overrides[key].en), tokens(vendorEn[key].message), key);
    }
  }
  // The DNR permission is granted at install: no module text asks to restart the browser for it any more.
  for (const key of Object.keys(catalog.ru)) {
    assert.equal(/перезапуск[а-я]* браузера/i.test(catalog.ru[key].message), false, key + ' (ru) still asks for a browser restart');
    assert.equal(/browser restart/i.test(catalog.en[key].message), false, key + ' (en) still asks for a browser restart');
  }
});

test('every key the UI bundle asks for (msg / module t) exists in the catalog', () => {
  const ui = readFileSync(join(root, 'apps/production-extension/protect-ui.js'), 'utf8');
  const shimAt = ui.indexOf('// ../../apps/production-protect/src/ui/i18n-shim.ts');
  assert.ok(shimAt > 0, 'shim module in protect-ui.js');
  const translate = /\nvar ([A-Za-z_$][\w$]*) = \(key, subs\) => \{/.exec(ui.slice(shimAt))?.[1];
  assert.ok(translate !== undefined, 'module t in protect-ui.js');
  const callee = new RegExp('\\b(?:msg|' + translate.replace(/\$/g, '\\$') + ')\\("([a-z][a-z0-9]*(?:_[a-z0-9]+)+)"', 'g');
  const used = new Set([...ui.matchAll(callee)].map((m) => m[1]));
  assert.ok(used.size > 300, 'keys used by literal: ' + used.size);
  const missing = [...used].filter((key) => !Object.hasOwn(catalog.en, key) && !Object.hasOwn(launcher.en, key) && !Object.hasOwn(branding.messages.en, key) && !Object.hasOwn(findings.en, key));
  assert.deepEqual(missing, []);
  // The embedded catalog is the generated file (ru and en), byte for byte as JSON values.
  for (const key of ['protect_title', 'fw_blocking_restart', 'protect_locale_fallback_note']) {
    assert.ok(ui.includes(JSON.stringify(catalog.ru[key].message)), key + ' (ru) embedded');
    assert.ok(ui.includes(JSON.stringify(catalog.en[key].message)), key + ' (en) embedded');
  }
});

test('language mapping: ru -> ru, the other 20 production languages -> en with the fallback note', async () => {
  const shim = await load(join(root, 'apps/production-protect/src/ui/i18n-shim.ts'));
  assert.equal(PRODUCTION_LANGUAGES.length, 21);
  for (const { id } of PRODUCTION_LANGUAGES) {
    const module = id === 'ru' ? 'ru' : 'en';
    assert.equal(shim.moduleLocaleOf(id), module, id);
    assert.equal(shim.isFallbackLocale(id), id !== 'ru' && id !== 'en', id);
    shim.setProductionLocale(id);
    assert.equal(shim.uiLocale(), module, id);
    assert.equal(shim.t('protect_title'), 'Firewall', id);
    assert.equal(shim.t('fw_blocking_restart'), catalog[module].fw_blocking_restart.message, id);
  }
  shim.setProductionLocale('ru');
  assert.equal(shim.tOptional('no_such_module_key'), null);
  assert.equal(shim.t('no_such_module_key'), 'no_such_module_key', 'missing key falls back to the key (caught by the native raw-key scan)');
});

test('production _locales carry no module key (the module texts live only in its own catalog)', () => {
  const own = new Set(Object.keys(ownRu));
  const moduleOnly = Object.keys(catalog.ru).filter((key) => /^(protect_|fw_|history_|replay_)/.test(key));
  const dir = join(root, 'apps/production-extension/_locales');
  for (const language of readdirSync(dir)) {
    const messages = readJson(join(dir, language, 'messages.json'));
    for (const key of own) assert.equal(Object.hasOwn(messages, key), false, language + ': ' + key);
    for (const key of moduleOnly) assert.equal(Object.hasOwn(messages, key), false, language + ': ' + key);
  }
});
